  return `${b.model.trim().toLowerCase()}|${(b.name || "").trim().toLowerCase()}|${b.color.trim().toLowerCase()}|${(b.variation || "").trim().toLowerCase()}|${(b.year || "").trim().toLowerCase()}`;
};"

